Unit Test Code:
#include "unity.h"
#include "buffer.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) { malloc_reset(); }

void unit_test_buffer_compact_allocation_failure(void) {
    // Setup: create a buffer with extra capacity and some data
    buffer_t *buf = buffer_new_with_size(32); // 2 allocations: struct + data
    TEST_ASSERT_NOT_NULL(buf);

    // Fill buffer with a string shorter than its capacity
    const char *test_str = "hello world";
    int ret = buffer_append(buf, test_str);
    TEST_ASSERT_EQUAL_INT(0, ret);

    // Confirm buffer has extra capacity
    size_t orig_size = buffer_size(buf);
    size_t orig_length = buffer_length(buf);
    TEST_ASSERT_TRUE(orig_size > orig_length);

    // Simulate calloc failure for the allocation in buffer_compact
    // 2 allocations already done in setup, so fail the next one (calloc in buffer_compact)
    malloc_fail_after(2);

    // Call function under test
    ssize_t compact_ret = buffer_compact(buf);

    // Assert: should return -1 on allocation failure
    TEST_ASSERT_EQUAL_INT(-1, compact_ret);

    // Assert: buffer remains unchanged
    helper_assert_buffer_string_equals(buf, test_str);
    helper_assert_buffer_length(buf, orig_length);
    helper_assert_buffer_size(buf, orig_size);

    // Cleanup
    buffer_free(buf);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_buffer_compact_allocation_failure);
    return UNITY_END();
}


